def main():
    path = ROOT / "frontend/src/locales/th.json"
    original = path.read_bytes()
    backup = TASK / "thai-catalogue-before-cf1.json"
    if not backup.exists():
        backup.write_bytes(original)
    catalogue = json.loads(original)
    catalogue.update(TRANSLATIONS)
    path.write_text(json.dumps(catalogue, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    write(ROOT / "frontend/src/__fixtures__/cf1-equal-10.json", view())
    print(f"Prepared {len(TRANSLATIONS)} study translations and real-adapter fixture")


if __name__ == "__main__":
    main()
